package com.resumeanalyzer.exception;
import org.springframework.http.*; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MaxUploadSizeExceededException; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { public record ApiError(Instant timestamp,int status,String error,String message,Map<String,String> validationErrors){} @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ApiError> notFound(RuntimeException e){return response(HttpStatus.NOT_FOUND,e.getMessage(),Map.of());} @ExceptionHandler({UnauthorizedException.class,BadCredentialsException.class}) ResponseEntity<ApiError> unauthorized(RuntimeException e){return response(HttpStatus.UNAUTHORIZED,e.getMessage(),Map.of());} @ExceptionHandler({BadRequestException.class,MaxUploadSizeExceededException.class}) ResponseEntity<ApiError> badRequest(RuntimeException e){return response(HttpStatus.BAD_REQUEST,e.getMessage(),Map.of());} @ExceptionHandler(IllegalStateException.class) ResponseEntity<ApiError> serviceUnavailable(IllegalStateException e){return response(HttpStatus.SERVICE_UNAVAILABLE,e.getMessage(),Map.of());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e){Map<String,String> fields=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.putIfAbsent(x.getField(),x.getDefaultMessage()));return response(HttpStatus.BAD_REQUEST,"Request validation failed",fields);} @ExceptionHandler(Exception.class) ResponseEntity<ApiError> unknown(Exception e){return response(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred",Map.of());} private ResponseEntity<ApiError> response(HttpStatus s,String message,Map<String,String> fields){return ResponseEntity.status(s).body(new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),message,fields));} }
